// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        vm.assume(assertionId != bytes32(0));
        vm.prank(address(c.optimisticAsserter()));
        c.assertionDisputedCallback(assertionId);
        int256 price = c.getPrice(bytes32(uint256(0x01)), 0, "");
        assertTrue(price == 0);
    }
}
